UPDATE businesses SET description = 'Alu Fox is a manufacturer and installer of aluminium and glass products, operating from a factory in Derdepoort, Pretoria, and serving clients nationwide. The company was established in 2020, and its team brings more than 30 years of combined experience in aluminium and glass work. Its product range includes custom windows and doors in stacking, sliding, folding, hinged, standard and frameless configurations, along with top-hung and slide-hung variants built to order. Alu Fox also supplies glass and mirror products made to building-regulation requirements, skylights and glass roofing designed to bring natural light into interiors, frameless showers manufactured to each customer''s specifications, balustrades, and automated door systems. The business reports having completed more than 250 projects and over 500 installations across residential and commercial settings, covering everything from window and door fittings to full glass-roofing and shower installations.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.alufox.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'alu-fox-kameeldrift' AND description = 'Alu Fox is an aluminium and glass manufacturer in Kameeldrift, Pretoria, established in 2020, specialising in aluminium windows, doors and frameless showers for residential and commercial projects.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
