UPDATE businesses SET description = 'Ancil Research Laboratories, based in Alphen Park, Pretoria, is a technology company that designs and develops a wide range of specialised electronic systems. Its product and project lines include radio-frequency identification asset-tracking systems, GSM payphones, train-integrity monitoring, ISM radio modems, telephone voice recorders, remote meter-reading equipment, and PCM/G3 transceivers for rural telecommunication systems. The company has also developed a mobile surveillance system known as WildFinder, a prison cellphone detector, a group decision-support system called TradeOff, an aviation antenna and SpeedPanel display, an animal-tranquilliser dart tracking system, a hand-held Yagi antenna, and load-switch equipment. Further projects cover baby and prisoner tagging devices, general asset tracking, sinewave UPS units, notification devices, a pseudo-Doppler direction finder and a motion detector, presented on the company''s website as current products and projects developed through its own engineering and research work.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.ancil.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'ancil-research-laboratories-alphen-park' AND description = 'Ancil Research Laboratories is a Pretoria technology company developing RFID asset-tracking systems, GSM payphones, remote meter reading and mobile surveillance systems for telecommunications, security and research clients.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
