UPDATE businesses SET description = 'Avis operates a car rental branch, known as Pretoria Downtown, at 70 Francis Baard Street in Pretoria, as part of the international Avis Rent a Car network. The branch is open Monday to Friday from 07:00 to 18:00, Saturdays from 08:00 to 13:00, and Sundays from 08:00 to 12:00. Its standard return policy requires rental vehicles to be brought back to the branch during its operating hours; where a location offers an after-hours key-drop box, a customer who leaves a vehicle outside those hours remains responsible for it and for any related charges, including damage or theft, until the contract can be closed on the next business day. Where no drop box is available, the branch does not permit vehicles to be left after closing, and customers must either return the car once the branch reopens or arrange to change the drop-off location to the nearest regional airport, at their own cost.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.avis.com/en/locations/af/za/pretoria/py1'), description_enriched_at = datetime('now') WHERE slug = 'avis-pretoria-central' AND description = 'AVIS is a car rental branch on Francis Baard Street in Pretoria, part of the international Avis Rent a Car network offering daily and long-term vehicle hire.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
