-- bay-tree-guest-house-baileys-muckleneuk (researched)
UPDATE businesses SET description = 'Bay Tree Guest House, in the quiet, jacaranda-lined suburb of Bailey''s Muckleneuk — generally regarded as part of Brooklyn, Pretoria — offers four-star accommodation in seven spacious en suite rooms. The guest house sits on the Gautrain bus route and is close to the South African Bureau of Standards, numerous foreign embassies and consulates, several hospitals, the Pretoria Advocates Chambers, the South African National Accreditation System, the South African Council for the Blind, Optima college, the University of Pretoria and the University of South Africa, as well as the offices of the Auditor-General and the South African Revenue Service. Nearby visitor attractions include Loftus Versfeld Stadium, the Austin Roberts Bird Sanctuary, the Union Buildings, the Voortrekker Monument and Brooklyn Mall. Guest amenities include free Wi-Fi throughout the property, solar power that keeps the guest house running during loadshedding, air-conditioned en suite rooms, some with self-catering facilities, DSTV, safe off-street parking, a swimming pool and lapa area, gardens planted with cycads, clivias and orchids, and an optional full English breakfast.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.baytree.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'bay-tree-guest-house-baileys-muckleneuk' AND description = 'Bay Tree Guest House is a guest house in Baileys Muckleneuk, Pretoria, offering rooms with an outdoor pool, garden and free WiFi close to the Brooklyn area.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
