UPDATE businesses SET description = 'Co.Space Entrepreneur Village in Pretoria, near the corner of Simon Vermooten and Bronkhorstspruit roads in Derdepoort, offers more than 280 individual commercial workspaces for month-to-month rental, without longer lease commitments. The site, about a kilometre from the M4 highway, is divided into several workspace types. Offices of 15 to 30 square metres come with shopfronts and, in some units, air conditioning and a mezzanine level, along with access to printing services and business training. Warehouses and workshops of up to 50 and 60 square metres respectively include double-volume space, a dispatch and delivery service and 24-hour security, with workshops also offering three-phase electricity and prepaid water. Commercial kitchens of 24 to 60 square metres are fitted with three-phase electricity, prepaid gas and water, extraction hoods and grease traps. Co.Space also offers hot-desking through its on-site business hub for entrepreneurs who need a workspace without a dedicated unit.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://cospace.co.za/pretoria/'), description_enriched_at = datetime('now') WHERE slug = 'co-space-entrepreneur-village-pretoria-derdepoort' AND description = 'Co.Space Entrepreneur Village Pretoria offers flexible, month-to-month workspace rentals including offices, warehouses, studios, workshops, commercial kitchens and event space near the Simon Vermooten and Bronkhorstspruit intersection.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
